def buildgrid(pos):
    # pos dict color: 'T' or 'B'
    out=[[0]*19 for _ in range(28)]
    shapes={
      4:[(0,0),(0,1),(1,1),(2,1),(3,1)],
      8:[(0,4),(1,1),(1,2),(1,3),(2,1),(2,2),(2,3),(3,1),(3,2),(3,3),(4,0)],
      9:[(0,0),(0,1),(0,2),(0,3),(0,4),(1,2),(2,2)],
      6:[(0,2),(1,2),(2,0),(2,1),(2,2),(3,2),(4,2)]}
    starts={4:(4,0),8:(5,4),9:(11,11),6:(17,2)}
    for col, cells in shapes.items():
        h=max(r for r,c in cells)+1
        dy=0 if pos[col]=='T' else 28-h
        r0,c0=starts[col]
        for r,c in cells:
            rr=dy+r;cc=c0+c
            if out[rr][cc]!=0: raise ValueError(('collision',col,rr,cc))
            out[rr][cc]=col
    assert len(out)==28 and all(len(row)==19 for row in out)
    return out
comb1=buildgrid({4:'B',8:'B',9:'T',6:'T'})
